#include "stdlib/math/base/special/polevl.h"
#include "stdlib/math/base/assert/is_nan.h"

/**
* Evaluates a polynomial using Horner's rule.
*
* @param x     input value
* @param coef  polynomial coefficients
* @param N     degree of the polynomial
* @return      polynomial value
*
* @example
* double coef[] = { 1.0, 2.0, 3.0 };
* double v = stdlib_base_polevl( 2.0, coef, 2 );
* // returns 17.0
*/
double stdlib_base_polevl( const double x, const double coef[], const int N ) {
	double ans;
	int i;

	// Check for NaN input for x
	if ( stdlib_base_is_nan( x ) ) {
		return 0.0 / 0.0; // NaN
	}

	ans = coef[ N ];
	for ( i = N-1; i >= 0 ; i-- ) {
		ans = ( ans * x ) + coef[ i ];
	}
	return ans;
}
